import { foreignKey, index, integer, pgTable, text, timestamp } from 'drizzle-orm/pg-core'
import { harness_topic } from './harness'

/**
 * Persisted snapshot of background subagent sessions (the basis for cold recovery).
 *
 * Design tradeoffs:
 * - **One table + JSON columns**: a session's event stream and message history are append-only
 *   plain JSON with small per-session volume; not splitting out an event table avoids "one row per
 *   token" write amplification and makes whole-transaction overwrites easy;
 * - `id` uses a stable id generated by the registry (`subagent-<uuid>`) rather than an in-process
 *   auto-increment counter;
 * - `config` stores **a snapshot of the subagent config at creation time**: even if the subagent is
 *   later edited or deleted in settings, historical sessions can still replay with the prompts and
 *   tools of that time, so config drift does not make old records unreadable;
 * - `status` never persists running: after an app crash/exit nothing is running, so recovery marks
 *   everything `inactive` and history is read-only at first; the first continuation cold-recovers
 *   from the snapshot (rebuilding model/tools/prompt) and then switches back to idle.
 */
export const subagent_session = pgTable(
  'subagent_session',
  {
    id: text().primaryKey().notNull(),
    topic_id: integer().notNull(),
    /** Subagent identifier (agent_config.name) */
    name: text().notNull(),
    /** Display name in the top bar (generated in the UI language active at creation time) */
    label: text().notNull(),
    /** First-round task instruction (session view title / legacy contract compatibility) */
    prompt: text().notNull(),
    /** Subagent config snapshot (JSON: SubAgentConfig) */
    config: text().notNull(),
    /** Message history (JSON: [{role:'human'|'ai', content}], used to rebuild context on continuation) */
    messages: text().notNull(),
    /** Session event stream (JSON: SubagentConversationEvent[], replayed by the renderer) */
    conversation: text().notNull(),
    conversation_seq: integer().notNull().default(0),
    /** Main model descriptor at spawn time: provider row id + model name (cold recovery returns to the same model; empty = default provider) */
    main_model_provider_id: integer(),
    main_model_name: text(),
    /** Session's cumulative real token usage (summed from each round's model usage_metadata; 0 = not captured) */
    usage_input_tokens: integer().notNull().default(0),
    usage_output_tokens: integer().notNull().default(0),
    usage_total_tokens: integer().notNull().default(0),
    usage_calls: integer().notNull().default(0),
    turn_counter: integer().notNull().default(0),
    /** Latest round's terminal state: completed / failed / killed */
    last_status: text(),
    last_output: text(),
    /** Queued messages not yet started (JSON: string[]; kept for display after recovery, replay needs continuation support) */
    inbox: text(),
    created_at: timestamp({ mode: 'string' }).defaultNow(),
    last_run_at: timestamp({ mode: 'string' }),
    updated_at: timestamp({ mode: 'string' }).defaultNow()
  },
  (table) => [
    index('idx_subagent_session_topic').using(
      'btree',
      table.topic_id.asc().nullsLast().op('int4_ops')
    ),
    foreignKey({
      columns: [table.topic_id],
      foreignColumns: [harness_topic.id],
      name: 'subagent_session_topic_id_fkey'
    }).onDelete('cascade')
  ]
)
